    <div class="scrim" id="paused" hidden><div class="pause-card overlay-card"><div class="card-eyebrow">TAKE A BREATHER</div><h2>Ready when you are.</h2><p>Your run is paused.</p><button id="resume" class="primary-button">Back to play ${L.arrow}</button><button id="pause-retry" class="secondary-button">Start again ${L.reset}</button></div></div>
